B.a2c=new A.bf("Continua",null,null,null,null,null,null,null,null,null,null)
B.a2e=new A.bf("I dati presenti nell\u2019app verranno sostituiti con quelli contenuti nel file selezionato.",null,null,null,null,null,null,null,null,null,null)
B.a2f=new A.bf("Le modifiche si applicano alle nuove registrazioni. Lo storico conserva il valore originale.",null,null,null,null,null,null,null,null,null,null)
B.a2g=new A.bf("Famiglia colore",null,B.dg,null,null,null,null,null,null,null,null)
B.ZR=new A.v(!0,null,null,null,null,null,18,B.an,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null,null)
B.a2h=new A.bf("Ancora nessuna giornata",null,B.ZR,B.bV,null,null,null,null,null,null,null)
B.a2i=new A.bf("Il relativo accredito sar\xe0 stornato.",null,null,null,null,null,null,null,null,null,null)
B.a2l=new A.bf("Eliminare la validazione?",null,null,null,null,null,null,null,null,null,null)
B.a2m=new A.bf("Il tuo Giorno Zero",null,B.nR,null,null,null,null,null,null,null,null)
B.a2n=new A.bf("Ripristinare il backup?",null,null,null,null,null,null,null,null,null,null)
B.a2o=new A.bf("Aggiungi voce",null,null,null,null,null,null,null,null,null,null)
B.a2p=new A.bf("Il 1\xb0 gennaio la quota si aggiunge al residuo. Alla prima configurazione il saldo resta invariato; la ricarica parte dal prossimo gennaio.",null,null,null,null,null,null,null,null,null,null)
B.a2q=new A.bf("Conferma",null,null,null,null,null,null,null,null,null,null)
B.a2r=new A.bf("Backup",null,B.dg,null,null,null,null,null,null,null,null)
B.a2t=new A.bf("Il saldo iniziale resta invariato. Saranno conteggiati i movimenti dalla data scelta, compresa. La scelta viene richiesta una sola volta.",null,null,null,null,null,null,null,null,null,null)
B.a2u=new A.bf("Pi\xf9 recenti in alto. Ogni nuovo saldo avvia un ciclo: i movimenti gi\xe0 compresi non vengono scalati di nuovo. I movimenti storici senza ora nello stesso giorno si considerano gi\xe0 inclusi.",null,null,null,null,null,null,null,null,null,null)
